public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType == null || targetType == null) return null;
    if (!(genericType instanceof ParameterizedType)) return null;
    ParameterizedType pType = (ParameterizedType) genericType;
    Type raw = pType.getRawType();
    if (!(raw instanceof Class)) return null;
    Class<?> rawClass = (Class<?>) raw;
    // Find mapping from type variables to actual types for targetType relative to rawClass
    Map<TypeVariable<?>, Type> typeVarAssigns = getTypeArguments(targetType, rawClass);
    if (typeVarAssigns == null) return null;
    Type[] actualTypeArgs = pType.getActualTypeArguments();
    Class<?>[] result = new Class<?>[actualTypeArgs.length];
    for (int i=0; i<actualTypeArgs.length; i++) {
        Type arg = actualTypeArgs[i];
        Type resolved = resolveType(arg, typeVarAssigns);
        if (resolved instanceof Class) {
            result[i] = (Class<?>) resolved;
        } else if (resolved instanceof ParameterizedType) {
            // get raw type
            Type rt = ((ParameterizedType) resolved).getRawType();
            if (rt instanceof Class) {
                result[i] = (Class<?>) rt;
            } else {
                return null;
            }
        } else if (resolved instanceof GenericArrayType) {
            // get component type
            Type comp = ((GenericArrayType) resolved).getGenericComponentType();
            Class<?> compClass = resolveComponentClass(comp, typeVarAssigns);
            if (compClass == null) return null;
            result[i] = Array.newInstance(compClass, 0).getClass();
        } else {
            return null;
        }
    }
    return result;
}

