public static void createConfigurationDirectory() {
    try {
        String osName = System.getProperty("os.name");
        String osVersion = System.getProperty("os.version");
        File dir;
        if (osName != null && osName.contains("Windows") && osVersion != null && osVersion.startsWith("5.")) {
            // Windows 2000
            String homeDrive = System.getenv("HOMEDRIVE");
            if (homeDrive == null) {
                homeDrive = System.getProperty("user.home");
            }
            File docsAndSettings = new File(homeDrive + "Documents and Settings");
            dir = new File(docsAndSettings, "lf5");
        } else {
            String userHome = System.getProperty("user.home");
            if (userHome == null) {
                throw new RuntimeException("Cannot determine user home directory");
            }
            dir = new File(userHome, "lf5");
        }
        if (!dir.exists()) {
            if (!dir.mkdirs()) {
                throw new RuntimeException("Failed to create configuration directory: " + dir.getAbsolutePath());
            }
        }
    } catch (Exception e) {
        throw new RuntimeException("Error creating configuration directory", e);
    }
}

