public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("str");
    }
    if (index < 0 || len < 0 || index > str.length() - len) {
        throw new IndexOutOfBoundsException("index or len out of bounds");
    }
    long size = 0;
    int end = index + len;
    for (int i = index; i < end; ) {
        char ch = str.charAt(i);
        int cp;
        if (Character.isHighSurrogate(ch) && i + 1 < end) {
            char low = str.charAt(i + 1);
            if (Character.isLowSurrogate(low)) {
                cp = Character.toCodePoint(ch, low);
                i += 2;
            } else {
                // unmatched high surrogate
                cp = 0xFFFD;
                i++;
            }
        } else if (Character.isLowSurrogate(ch)) {
            // unmatched low surrogate
            cp = 0xFFFD;
            i++;
        } else {
            cp = ch;
            i++;
        }
        if (cp <= 0x7F) {
            size += 1;
        } else if (cp <= 0x7FF) {
            size += 2;
        } else if (cp <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }
        if (size > Integer.MAX_VALUE) {
            throw new ArithmeticException("UTF-8 size exceeds int range");
        }
    }
    return (int) size;
}

