public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    if (box == null) {
        throw new IllegalArgumentException("box cannot be null");
    }
    try {
        double minX = box.getMinX();
        double minY = box.getMinY();
        double maxX = box.getMaxX();
        double maxY = box.getMaxY();

        if (minX > maxX || minY > maxY) {
            throw new IllegalArgumentException("Invalid box coordinates: min values must be less than or equal to max values");
        }

        double centerX = (minX + maxX) / 2.0;

        Box2D left = new Box2D(minX, minY, centerX, maxY);
        Box2D right = new Box2D(centerX, minY, maxX, maxY);

        return new Pair<>(left, right);
    } catch (Exception e) {
        throw new RuntimeException("Failed to split box along X axis", e);
    }
}

private void enlarge(final int size) {
    if (size <= 0) {
        return;
    }
    if (size < 0) {
        throw new IllegalArgumentException("Size must be non-negative");
    }
    if (bytes == null) {
        bytes = new byte[size];
        return;
    }
    int currentCapacity = bytes.length;
    long newCapLong = Math.max((long) currentCapacity * 2, (long) currentCapacity + size);
    if (newCapLong > Integer.MAX_VALUE) {
        newCapLong = Integer.MAX_VALUE;
    }
    int newCapacity = (int) newCapLong;
    try {
        byte[] newBytes = new byte[newCapacity];
        System.arraycopy(bytes, 0, newBytes, 0, currentCapacity);
        bytes = newBytes;
    } catch (OutOfMemoryError e) {
        throw new OutOfMemoryError("Unable to enlarge byte vector to capacity " + newCapacity);
    }
}

