                    break;
                case 0x08: // Uninitialized
                    int offset = type.getOffset(); // offset of the new instruction
                    stackMapTableEntries.write((offset >> 8) & 0xFF);
                    stackMapTableEntries.write(offset & 0xFF);
                    break;
                default:
                    // No additional data for other tags
                    break;
            }
        }
    } catch (IOException e) {
        // stackMapTableEntries is expected to be a ByteArrayOutputStream or similar that does not throw IOException,
