        return false;
    }

    // Convert the target string to lower case once for case-insensitive comparison
    String lowerStr = str.toLowerCase();

    // Iterate over each search string
    for (String search : searchStrArray) {
        if (search == null || search.isEmpty()) {
            continue; // Skip null or empty search strings
        }

        // Convert the search string to lower case
        String lowerSearch = search.toLowerCase();

        // Check each character in the search string
        for (int i = 0; i < lowerSearch.length(); i++) {
            char ch = lowerSearch.charAt(i);
            if (lowerStr.indexOf(ch) != -1) {
                return true; // Found a matching character
            }
        }
    }

    // No matching character found
    return false;
}

