public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c != '\\') {
            sb.append(c);
            continue;
        }
        // Escape sequence
        i++;
        if (i >= len) {
            throw new IllegalArgumentException("Trailing backslash in string");
        }
        char next = str.charAt(i);
        switch (next) {
            case 'n':
                sb.append('\n');
                break;
            case 't':
                sb.append('\t');
                break;
            case 'r':
                sb.append('\r');
                break;
            case 'b':
                sb.append('\b');
                break;
            case 'f':
                sb.append('\f');
                break;
            case '\\':
                sb.append('\\');
                break;
            case '\'':
                sb.append('\'');
                break;
            case '\"':
                sb.append('\"');
                break;
            case 'u':
                if (i + 4 >= len) {
                    throw new IllegalArgumentException("Incomplete Unicode escape sequence");
                }
                String hex = str.substring(i + 1, i + 5);
                try {
                    int code = Integer.parseInt(hex, 16);
                    sb.append((char) code);
                } catch (NumberFormatException e) {
                    throw new IllegalArgumentException("Invalid Unicode escape sequence: \\u" + hex);
                }
                i += 4;
                break;
            default:
                if (next >= '0' && next <= '7') {
                    int j = i;
                    int count = 0;
                    while (j < len && count < 3 && str.charAt(j) >= '0' && str.charAt(j) <= '7') {
                        j++;
                        count++;
                    }
                    String oct = str.substring(i, j);
                    try {
                        int code = Integer.parseInt(oct, 8);
                        sb.append((char) code);
                    } catch (NumberFormatException e) {
                        throw new IllegalArgumentException("Invalid octal escape sequence: \\" + oct);
                    }
                    i = j - 1;
                } else {
                    throw new IllegalArgumentException("Invalid escape sequence: \\" + next);
                }
                break;
        }
    }
    return sb.toString();
}

