    return (short) ((high << 8) | low);
}

private static Object copyArrayGrow1(final Object array, final Class<?> newArrayComponentType) {
    // If the input array is null, create a new array of size 1 with the specified component type.
    if (array == null) {
        if (newArrayComponentType == null) {
            throw new IllegalArgumentException("newArrayComponentType must not be null when array is null");
        }
        return java.lang.reflect.Array.newInstance(newArrayComponentType, 1);
    }

    // Ensure the provided object is actually an array.
    Class<?> arrayClass = array.getClass();
    if (!arrayClass.isArray()) {
        throw new IllegalArgumentException("Provided object is not an array");
    }

    // Determine the component type and current length.
    Class<?> componentType = arrayClass.getComponentType();
    int oldLength = java.lang.reflect.Array.getLength(array);

    // Create a new array with one additional slot.
    Object newArray = java.lang.reflect.Array.newInstance(componentType, oldLength + 1);

    // Copy the old array contents into the new array.
    System.arraycopy(array, 0, newArray, 0, oldLength);

    // The last element remains at its default value (null for reference types, 0 for primitives).
    return newArray;
}

