private String unescapeId(String input){
    if (input == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(input.length());
    int len = input.length();
    for (int i = 0; i < len; i++) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < len) {
            char next = input.charAt(i + 1);
            switch (next) {
                case 'n':
                    sb.append('\n');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case 'b':
                    sb.append('\b');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case '0':
                    sb.append('\0');
                    break;
                case '\"':
                    sb.append('\"');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                default:
                    sb.append(next);
                    break;
            }
            i++; // skip the escaped character
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

public static String[] concatenateStringArrays(String[] array1, String[] array2) {
    // If both arrays are null, return null as specified
    if (array1 == null && array2 == null) {
        return null;
    }
    // If one of the arrays is null, return a clone of the other array
    if (array1 == null) {
        return array2.clone();
    }
    if (array2 == null) {
        return array1.clone();
    }
    // Both arrays are non-null: concatenate them
    String[] result = new String[array1.length + array2.length];
    System.arraycopy(array1, 0, result, 0, array1.length);
    System.arraycopy(array2, 0, result, array1.length, array2.length);
    return result;
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Validate inputs
    if (bucketsByLabel == null || labels == null) {
        return;
    }
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        return;
    }
    // If the source bucket is the same as the target bucket, nothing to do
    if (minLabel == 0) {
        return;
    }

    Set<Integer> source = bucketsByLabel.get(minLabel);
    if (source == null || source.isEmpty()) {
        return;
    }

    // Ensure the target bucket (label 0) exists
    Set<Integer> target = bucketsByLabel.get(0);
    if (target == null) {
        target = new java.util.HashSet<>();
        bucketsByLabel.set(0, target);
    }

    // Move vertices from source to target and update labels
    for (Integer v : source) {
        if (v == null) {
            continue;
        }
        target.add(v);
        if (v >= 0 && v < labels.size()) {
            labels.set(v, 0);
        }
    }

    // Clear the source bucket
    source.clear();
}

public static String[] addStringToArray(String[] array, String str) {
    // If the input array is null, simply return a new array containing the string.
    if (array == null) {
        return new String[]{str};
    }

    // Create a new array with one additional slot for the new string.
    String[] result = new String[array.length + 1];

    // Copy the original array contents into the new array.
    System.arraycopy(array, 0, result, 0, array.length);

    // Append the new string at the end.
    result[array.length] = str;

    return result;
}

public static int countOccurrencesOf(String str, String sub) {
    if (str == null || sub == null || sub.isEmpty()) {
        return 0;
    }
    int count = 0;
    int index = 0;
    while ((index = str.indexOf(sub, index)) != -1) {
        count++;
        index++; // allow overlapping occurrences
    }
    return count;
}

