private String parseToken(final char[] terminators) {
    // Validate the terminators array
    if (terminators == null) {
        throw new IllegalArgumentException("terminators array cannot be null");
    }

    // Ensure the input source is available
    if (input == null) {
        throw new IllegalStateException("Input source is not initialized");
    }

    // If the current position is already at or beyond the end of the input,
    // return an empty token immediately.
    if (pos >= input.length()) {
        return "";
    }

    // Build the token character by character
    StringBuilder token = new StringBuilder();
    while (pos < input.length()) {
        char current = input.charAt(pos);

        // Check if the current character is one of the terminators
        boolean isTerminator = false;
        for (char term : terminators) {
            if (current == term) {
                isTerminator = true;
                break;
            }
        }

        // Stop parsing when a terminator is encountered
        if (isTerminator) {
            break;
        }

        // Append the character to the token and advance the position
        token.append(current);
        pos++;
    }

    return token.toString();
}

