private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null) {
        return new Pair<>(java.util.Collections.emptyList(), 0L);
    }
    int n = bounds.size();
    java.util.List<Integer> suffix = new java.util.ArrayList<>(n);
    long runningSum = 0L;
    for (int i = n - 1; i >= 0; i--) {
        Integer val = bounds.get(i);
        if (val == null) {
            throw new IllegalArgumentException("bounds contains null at index " + i);
        }
        runningSum += val;
        // Cast to int; assumes the suffix sum fits in int range
        suffix.add((int) runningSum);
    }
    java.util.Collections.reverse(suffix);
    long totalSum = runningSum;
    return new Pair<>(suffix, totalSum);
}

