        throw new IllegalArgumentException("Graph must not be null");
    }
    if (vertices == null) {
        throw new IllegalArgumentException("Vertices set must not be null");
    }
    // A null or empty set is trivially a clique
    if (vertices.isEmpty() || vertices.size() == 1) {
        return true;
    }
    // Convert to list for pair iteration
    List<V> list = new ArrayList<>(vertices);
    int n = list.size();
    for (int i = 0; i < n; i++) {
        V v1 = list.get(i);
        if (v1 == null) {
            throw new IllegalArgumentException("Vertices set contains null");
        }
        for (int j = i + 1; j < n; j++) {
            V v2 = list.get(j);
            if (v2 == null) {
                throw new IllegalArgumentException("Vertices set contains null");
            }
            if (!graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }
    return true;
