public static String applyRelativePath(String path, String relativePath) {
    if (path == null) {
        throw new IllegalArgumentException("path cannot be null");
    }
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }

    boolean isAbsolute = path.startsWith("/");
    String[] pathParts = path.split("/");
    String[] relParts = relativePath.split("/");

    java.util.Deque<String> stack = new java.util.ArrayDeque<>();

    // Add existing path components to stack
    for (String part : pathParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.removeLast();
            }
        } else {
            stack.addLast(part);
        }
    }

    // Process relative path components
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.removeLast();
            }
        } else {
            stack.addLast(part);
        }
    }

    // Build the resulting path
    StringBuilder result = new StringBuilder();
    if (isAbsolute) {
        result.append("/");
    }
    java.util.Iterator<String> it = stack.iterator();
    while (it.hasNext()) {
        result.append(it.next());
        if (it.hasNext()) {
            result.append("/");
        }
    }

    // If result is empty and path was absolute, return "/"
    if (result.length() == 0 && isAbsolute) {
        return "/";
    }
    // If result is empty and path was relative, return "."
    if (result.length() == 0) {
        return ".";
    }
    return result.toString();
}

