    if (array == null) {
        return null;
    }

    int nonNullCount = 0;
    for (Object obj : array) {
        if (obj != null) {
            nonNullCount++;
        }
    }

    // If there are no nulls, we can return the original array if it is already a String[]
    if (nonNullCount == array.length) {
        if (array instanceof String[]) {
            return (String[]) array;
        }
        // Create a new String[] with the same elements (they are all non-null)
        String[] result = new String[nonNullCount];
        try {
            for (int i = 0, j = 0; i < array.length; i++) {
                result[j++] = (String) array[i];
            }
        } catch (ClassCastException e) {
            throw new IllegalArgumentException("Array contains non-String elements", e);
        }
        return result;
    }

    // There are null elements; create a new array without them
    String[] result = new String[nonNullCount];
    int idx = 0;
    try {
        for (Object obj : array) {
            if (obj != null) {
                result[idx++] = (String) obj;
            }
        }
    } catch (ClassCastException e) {
        throw new IllegalArgumentException("Array contains non-String elements", e);
    }
    return result;
}

