public boolean isExpired(long timestamp, long expiredThreshold) {
    try {
        // If threshold is non-positive, consider the metric expired immediately.
        if (expiredThreshold <= 0) {
            return true;
        }
        // Current system time in milliseconds.
        long currentTime = System.currentTimeMillis();
        // If the timestamp is in the future or invalid, do not expire.
        if (timestamp <= 0 || timestamp > currentTime) {
            return false;
        }
        // Determine if the elapsed time since the last update exceeds the threshold.
        return (currentTime - timestamp) > expiredThreshold;
    } catch (Exception e) {
        // In case of any unexpected error, conservatively do not expire.
        return false;
    }
}

